const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    const pt = ee.Geometry.Point([125.93, -20.59]);
    const region = pt.buffer(10000); // 10 km
    // AWST (UTC+8): 11:00–14:00 on 2020-01-14 -> UTC windows
    const earlyStart = '2020-01-14T03:00:00Z';
    const earlyEnd = '2020-01-14T04:00:00Z';
    const earlyFallbackStart = '2020-01-14T02:00:00Z';
    const earlyFallbackEnd = '2020-01-14T04:00:00Z';
    const lateStart = '2020-01-14T05:00:00Z';
    const lateEnd = '2020-01-14T06:30:00Z';
    const lateFallbackEnd = '2020-01-14T07:00:00Z';

    // Helper to get first image from collection with window and bounds
    function getModisImage(collectionId, start, end) {
      return ee.ImageCollection(collectionId)
        .filterDate(start, end)
        .filterBounds(region)
        .select(['state_1km'])
        .sort('system:time_start')
        .first();
    }

    // Try earlier (near 11:00 AWST) with Terra
    let earlyCol = ee.ImageCollection('MODIS/061/MOD09GA')
      .filterDate(earlyStart, earlyEnd)
      .filterBounds(region)
      .select(['state_1km']);
    let earlySize = await earlyCol.size().getInfo();
    let earlyFallbackUsed = false;
    if (earlySize === 0) {
      earlyCol = ee.ImageCollection('MODIS/061/MOD09GA')
        .filterDate(earlyFallbackStart, earlyFallbackEnd)
        .filterBounds(region)
        .select(['state_1km'])
        .sort('system:time_start');
      earlySize = await earlyCol.size().getInfo();
      earlyFallbackUsed = earlySize > 0;
    }
    if (earlySize === 0) {
      console.log('Early window images (Terra): 0');
      console.log('Later window images (Aqua): TBD');
      console.log('C1: Empty Collection');
      console.log('C1');
      return;
    }
    const earlyImg = ee.Image(earlyCol.first());

    // Try later (near 14:00 AWST) with Aqua
    let lateCol = ee.ImageCollection('MODIS/061/MYD09GA')
      .filterDate(lateStart, lateEnd)
      .filterBounds(region)
      .select(['state_1km'])
      .sort('system:time_start');
    let lateSize = await lateCol.size().getInfo();
    let lateFallbackUsed = false;
    if (lateSize === 0) {
      lateCol = ee.ImageCollection('MODIS/061/MYD09GA')
        .filterDate(lateStart, lateFallbackEnd)
        .filterBounds(region)
        .select(['state_1km'])
        .sort('system:time_start');
      lateSize = await lateCol.size().getInfo();
      lateFallbackUsed = lateSize > 0;
    }
    if (lateSize === 0) {
      console.log(`Early window images (Terra): ${earlySize}${earlyFallbackUsed ? ' (fallback used)' : ''}`);
      console.log('Later window images (Aqua): 0');
      console.log('C1: Empty Collection');
      console.log('C1');
      return;
    }
    const lateImg = ee.Image(lateCol.first());

    // Function to compute cloud stats from state_1km
    async function cloudStats(img, label) {
      // Decode cloud state: bits 0-1 (0=clear, 1=cloudy, 2=mixed, 3=not set)
      const qa = img.select('state_1km');
      const cloudState = qa.bitwiseAnd(3);
      const cloudy = cloudState.eq(1).or(cloudState.eq(2)).updateMask(qa.mask());
      const validCount = await qa.reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: region,
        scale: 1000,
        maxPixels: 1e9
      }).get('state_1km').getInfo();
      const cloudCount = await cloudy.reduceRegion({
        reducer: ee.Reducer.sum(),
        geometry: region,
        scale: 1000,
        maxPixels: 1e9
      }).get('state_1km').getInfo();
      const timeUTC = await ee.Date(img.get('system:time_start')).format('YYYY-MM-dd HH:mm').getInfo();
      const timeLocal = await ee.Date(img.get('system:time_start')).advance(8, 'hour').format('YYYY-MM-dd HH:mm').getInfo();
      return {
        valid: validCount || 0,
        cloudy: cloudCount || 0,
        frac: (validCount && cloudCount != null) ? (cloudCount / validCount) : null,
        timeUTC,
        timeLocal,
        label
      };
    }

    const early = await cloudStats(earlyImg, 'Terra');
    const late = await cloudStats(lateImg, 'Aqua');

    // Check C2: No valid pixels
    if (early.valid === 0 || late.valid === 0) {
      console.log(`Early window images (Terra): ${earlySize}${earlyFallbackUsed ? ' (fallback used)' : ''}`);
      console.log(`Later window images (Aqua): ${lateSize}${lateFallbackUsed ? ' (fallback used)' : ''}`);
      console.log('No valid pixels after QA decoding.');
      console.log('C2: No Valid Pixels');
      console.log('C2');
      return;
    }

    // Validate fractions
    const invalidEarly = (early.frac === null) || isNaN(early.frac) || early.frac < 0 || early.frac > 1;
    const invalidLate = (late.frac === null) || isNaN(late.frac) || late.frac < 0 || late.frac > 1;
    if (invalidEarly || invalidLate) {
      console.log(`Early Img Time (AWST): ${early.timeLocal}, Valid: ${early.valid}, CloudPx: ${early.cloudy}`);
      console.log(`Late Img Time (AWST): ${late.timeLocal}, Valid: ${late.valid}, CloudPx: ${late.cloudy}`);
      console.log('C3: Calculation Failure (invalid cloud fraction)');
      console.log('C3');
      return;
    }

    // Print concise evidence
    console.log(`Early window images (Terra): ${earlySize}${earlyFallbackUsed ? ' (fallback used)' : ''}`);
    console.log(`Late window images (Aqua): ${lateSize}${lateFallbackUsed ? ' (fallback used)' : ''}`);
    console.log(`Terra @ ${early.timeLocal} AWST (UTC ${early.timeUTC})`);
    console.log(` - Cloud%: ${(early.frac * 100).toFixed(1)} | Valid px: ${early.valid}`);
    console.log(`Aqua  @ ${late.timeLocal} AWST (UTC ${late.timeUTC})`);
    console.log(` - Cloud%: ${(late.frac * 100).toFixed(1)} | Valid px: ${late.valid}`);

    // 5. Final Answer
    if (late.frac > early.frac) {
      console.log('A: Yes');
    } else {
      console.log('B: No');
    }
  } catch (err) {
    console.error('D: Processing error', err);
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
